package com.autocare.platform.order;
import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class EmbeddingFoundationTest {
 static EmbeddingProfile profile(){return new EmbeddingProfile("synthetic-fixture","a".repeat(40),3,"QUERY: ");}
 @Test void malformedKnowledgePayloadsFailAsBadInput(){for(String raw:List.of(" ","null","[]","{}","{\"embedding_allowed\":true}"))assertEquals(400,assertThrows(org.springframework.web.server.ResponseStatusException.class,()->KnowledgeInput.config(raw,false)).getStatusCode().value());assertThrows(IllegalArgumentException.class,()->new EmbeddingProfile("model","a".repeat(41),3,""));}
 @Test void fingerprintIncludesEveryProcessingChoice(){var p=profile();assertEquals(p.fingerprint(),profile().fingerprint());assertEquals(64,p.fingerprint().length());for(var other:List.of(new EmbeddingProfile("other","a".repeat(40),3,"QUERY: "),new EmbeddingProfile(p.model(),"b".repeat(40),3,p.queryPrefix()),new EmbeddingProfile(p.model(),p.revision(),4,p.queryPrefix()),new EmbeddingProfile(p.model(),p.revision(),3,"")))assertNotEquals(p.fingerprint(),other.fingerprint());}
 @Test void invalidConfigurationIsNotAccepted(){for(int n:List.of(0,1025))assertThrows(IllegalArgumentException.class,()->new EmbeddingProfile("model","a".repeat(40),n,""));assertThrows(IllegalArgumentException.class,()->new EmbeddingProfile("https://external","a".repeat(40),3,""));assertThrows(IllegalArgumentException.class,()->new EmbeddingProfile("model","latest",3,""));assertThrows(IllegalArgumentException.class,()->new EmbeddingProfile("model","a".repeat(40),3,"\ud800"));}
 @Test void chunkOffsetsPreserveUnicodeAndOverlapWithoutGaps(){String body="合成😀".repeat(700);var chunks=KnowledgeChunks.split(body);assertTrue(chunks.size()>1);int covered=0;for(int i=0;i<chunks.size();i++){var c=chunks.get(i);assertEquals(i,c.ordinal());assertEquals(c.text(),body.substring(c.start(),c.end()));assertTrue(c.text().codePointCount(0,c.text().length())<=256);assertTrue(c.start()<=covered);covered=c.end();if(i>0){var old=chunks.get(i-1);assertEquals(32,body.codePointCount(c.start(),old.end()));}}assertEquals(body.length(),covered);assertEquals(chunks,KnowledgeChunks.split(body));}
 @Test void maximumTextIsCompleteAndInvalidTextRefused(){var chunks=KnowledgeChunks.split("x".repeat(10000));assertTrue(chunks.size()<=64);assertEquals(10000,chunks.get(chunks.size()-1).end());for(String text:List.of(""," ","\ud800","x\u0000","x".repeat(10001)))assertThrows(IllegalArgumentException.class,()->KnowledgeChunks.split(text));}
 @Test void cosineAndNormalizationAreFiniteEvenForExtremeFiniteValues(){assertEquals(1,EmbeddingVectors.cosine(new double[]{2,0},new double[]{1,0}),1e-12);assertEquals(0,EmbeddingVectors.cosine(new double[]{1,0},new double[]{0,1}),1e-12);assertEquals(-1,EmbeddingVectors.cosine(new double[]{1,0},new double[]{-1,0}),1e-12);for(double v:new double[]{Double.MAX_VALUE,Double.MIN_VALUE})assertArrayEquals(new double[]{1,0},EmbeddingVectors.normalized(new double[]{v,0},2),1e-12);}
 @Test void zeroNonfiniteWrongDimensionsAndWrongProviderIdentityRefused(){for(double[] row:new double[][]{null,{},new double[]{0,0,0},new double[]{1,2},new double[]{Double.NaN,0,1},new double[]{Double.POSITIVE_INFINITY,0,1}})assertThrows(IllegalArgumentException.class,()->EmbeddingVectors.normalized(row,3));assertThrows(IllegalArgumentException.class,()->EmbeddingVectors.validate(new EmbeddingProvider.Output("b".repeat(64),List.of(new double[]{1,0,0})),profile(),1));assertThrows(IllegalArgumentException.class,()->EmbeddingVectors.validate(new EmbeddingProvider.Output(profile().fingerprint(),List.of()),profile(),1));}
 @Test void batchesAreAtMostFourAndInvalidPartialOutputIsNotPublished(){var batches=new ArrayList<Integer>();try(var executor=new EmbeddingExecutor(profile(),(p,texts)->{batches.add(texts.size());return new EmbeddingProvider.Output(p.fingerprint(),texts.stream().map(t->new double[]{1,0,0}).toList());},Duration.ofSeconds(1))){assertEquals(9,executor.call(Collections.nCopies(9,"synthetic")).size());assertEquals(List.of(4,4,1),batches);}try(var executor=new EmbeddingExecutor(profile(),(p,t)->new EmbeddingProvider.Output(p.fingerprint(),List.of()),Duration.ofSeconds(1))){assertEquals("INVALID_VECTOR",assertThrows(EmbeddingExecutor.Failed.class,()->executor.call(List.of("x"))).code);}}
 @Test void deadlineAndIgnoredInterruptionCannotCreateAnUnboundedQueue()throws Exception{
  var entered=new CountDownLatch(1);var release=new CountDownLatch(1);
  try(var executor=new EmbeddingExecutor(profile(),(p,texts)->{entered.countDown();while(release.getCount()>0)try{release.await();}catch(InterruptedException ignored){}return new EmbeddingProvider.Output(p.fingerprint(),List.of(new double[]{1,0,0}));},Duration.ofMillis(80))){
   assertEquals("UNAVAILABLE",assertThrows(EmbeddingExecutor.Failed.class,()->executor.call(List.of("x"))).code);assertEquals(0,entered.getCount());long start=System.nanoTime();assertThrows(EmbeddingExecutor.Failed.class,()->executor.call(List.of("y")));assertTrue(TimeUnit.NANOSECONDS.toMillis(System.nanoTime()-start)<100);release.countDown();
  }finally{release.countDown();}
 }
}
